{
  "headline": "FDA's records trace our supply to a plant classified OAI 214 days before the shortage posting",
  "headline_cites": ["D14"],
  "sentences": [
    {
      "text": "FDA first posted the furosemide injection shortage on 2020-04-07 and it remains current as of 2026-10-21.",
      "cites": ["E69", "E60"]
    },
    {
      "text": "An FDA inspection of Pfizer Healthcare India Private Limited ended 2019-09-06 and was classified OAI, with the classification letter dated 2020-05-25, 214 days before the shortage posting.",
      "cites": ["D14", "E56"]
    },
    {
      "text": "A Warning Letter was issued to Pfizer Healthcare India Private Limited on 2020-03-25, 13 days before the shortage posting.",
      "cites": ["D17", "E58"]
    },
    {
      "text": "Intas Pharmaceuticals Limited, another registered plant for Accord Healthcare's furosemide, received an OAI classification letter dated 2023-04-05 and a Warning Letter on 2023-07-28.",
      "cites": ["D18", "E14", "E15"]
    },
    {
      "text": "Hospira, Inc. (Pfizer) holds a current shortage listing for furosemide injection with NDC 0409-6102-02.",
      "cites": ["E67"]
    },
    {
      "text": "Corvale East has 8.5 days of furosemide 10 mg/mL 2 mL vials on hand, while Corvale Lakeside has 28 days and can spare 33 vials.",
      "cites": ["D1", "D3"]
    },
    {
      "text": "The recommended action is to transfer 33 vials from Corvale Lakeside to Corvale East, which would give Corvale East 12 days of supply while Corvale Lakeside retains 14 days.",
      "cites": ["D21"]
    }
  ]
}
